begin;
create temp table choice_probe as select gen_random_uuid() c,gen_random_uuid() team,gen_random_uuid() owner_id,gen_random_uuid() parent_id,gen_random_uuid() outsider_id,gen_random_uuid() l1,gen_random_uuid() l2,gen_random_uuid() l3;
grant select on choice_probe to authenticated,anon;
insert into public.clubs(id,name,status) select c,'Synthetic registration choices','active' from choice_probe;
insert into public.teams(id,club_id,name,age_group) select team,c,'Synthetic Team','U12' from choice_probe;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select u,u::text||'@choices.invalid',now(),jsonb_build_object('auth_entry','vereinsmarkt','market_terms_version','2026-11-17','market_show_team',false) from choice_probe,lateral unnest(array[owner_id,parent_id,outsider_id])u;
insert into private.exchange_members(club_id,user_id) select c,u from choice_probe,lateral unnest(array[owner_id,parent_id])u;
insert into private.exchange_member_teams(club_id,user_id,team_id) select c,u,team from choice_probe,lateral unnest(array[owner_id,parent_id])u;
create function pg_temp.check(ok boolean,msg text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAILED: %',msg;end if;end$$;
select pg_temp.check((select count(*)=3 from private.market_terms_acceptances where user_id in (select unnest(array[owner_id,parent_id,outsider_id]) from choice_probe)),'server registration evidence');
select pg_temp.check(not has_table_privilege('authenticated','private.market_terms_acceptances','select'),'private evidence denied');
select pg_temp.check(not has_function_privilege('authenticated','private.exchange_optional_team_label(uuid,uuid)','execute'),'no direct cross-user lookup');
select set_config('request.jwt.claim.sub',owner_id::text,true) from choice_probe;
set local role authenticated;
insert into public.exchange_listings(id,club_id,owner_id,title,category,size,condition,offer,status,photo_paths) select v,c,owner_id,'Synthetic item','Pulli','128','Gut','Gratis','Verfügbar',array[c::text||'/'||owner_id::text||'/'||v::text||'/11111111-1111-1111-1111-111111111111.jpg'] from choice_probe,lateral unnest(array[l1,l2])v;
reset role;
select set_config('request.jwt.claim.sub',parent_id::text,true) from choice_probe;
set local role authenticated;
insert into public.exchange_threads(listing_id,requester_id,requester_team_label) select l1,parent_id,'FORGED' from choice_probe;
select pg_temp.check((select requester_team_label='' from public.exchange_threads where listing_id=(select l1 from choice_probe)),'no opt-in and forged label hidden');
do $$begin begin update public.exchange_threads set requester_team_label='FORGED';raise exception 'UPDATE ACCEPTED';exception when insufficient_privilege then null;end;end$$;
reset role;
update auth.users set raw_user_meta_data=raw_user_meta_data||'{"market_show_team":true}'::jsonb where id=(select parent_id from choice_probe);
select set_config('request.jwt.claim.sub',parent_id::text,true) from choice_probe;
set local role authenticated;
insert into public.exchange_threads(listing_id,requester_id,requester_team_label) select l2,parent_id,'FORGED' from choice_probe;
select pg_temp.check((select requester_team_label='U12' from public.exchange_threads where listing_id=(select l2 from choice_probe)),'opt-in uses only assigned team');
insert into public.exchange_listings(id,club_id,owner_id,title,category,size,condition,offer,status,team_label,photo_paths) select l3,c,parent_id,'Own synthetic item','Pulli','128','Gut','Gratis','Verfügbar','U12',array[c::text||'/'||parent_id::text||'/'||l3::text||'/11111111-1111-1111-1111-111111111111.jpg'] from choice_probe;
reset role;
select set_config('request.jwt.claim.sub',outsider_id::text,true) from choice_probe;
set local role authenticated;
select pg_temp.check((select count(*)=0 from public.exchange_threads where listing_id in (select l1 from choice_probe union select l2 from choice_probe)),'outsider cannot see messages or team');
reset role;
update auth.users set raw_user_meta_data=raw_user_meta_data||'{"market_show_team":false}'::jsonb where id=(select parent_id from choice_probe);
select pg_temp.check(not exists(select 1 from public.exchange_threads where requester_id=(select parent_id from choice_probe) and requester_team_label<>''),'withdrawal clears existing requests');
select pg_temp.check((select team_label='' from public.exchange_listings where id=(select l3 from choice_probe)),'withdrawal clears existing listings');
update auth.users set raw_user_meta_data=raw_user_meta_data||'{"market_show_team":false,"market_terms_version":"invalid"}'::jsonb where id=(select parent_id from choice_probe);
select pg_temp.check((select count(*)=1 from private.market_terms_acceptances where user_id=(select parent_id from choice_probe)),'repeat/stale metadata cannot rewrite evidence');
select pg_temp.check((select accepted_at=transaction_timestamp() from private.market_terms_acceptances where user_id=(select parent_id from choice_probe)),'server timestamp retained');
select set_config('request.jwt.claim.sub','',true);
set local role anon;
do $$begin begin perform 1 from public.exchange_threads;raise exception 'ANON ACCEPTED';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
select 'PASS: private server acceptance evidence, default-off sharing, forged labels, assigned teams, role isolation, withdrawal and repeated metadata' result;
